css:
.caldorra-sim-container {
    padding: 24px;
    background: #f4f6f9;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}
.caldorra-sim-header {
    background: linear-gradient(135deg, #0f1d3a 0%, #1a2e5c 100%);
    color: #ffffff;
    padding: 32px 36px;
    margin-bottom: 24px;
    border-radius: 4px;
    border-left: 6px solid #c9a96e;
    box-shadow: 0 4px 12px rgba(15,29,58,0.15);
}
.caldorra-sim-header h1 {
    margin: 0;
    font-size: 1.5rem;
    font-weight: 600;
    letter-spacing: 0.02em;
    color: #ffffff;
}
.caldorra-sim-subtitle {
    font-size: 0.78rem;
    color: #c9a96e;
    margin-top: 10px;
    text-transform: uppercase;
    letter-spacing: 0.14em;
}
.caldorra-sim-period-bar {
    background: #ffffff;
    padding: 16px 24px;
    margin-bottom: 16px;
    border-radius: 4px;
    border: 1px solid #d8dee8;
    display: flex;
    justify-content: space-between;
    align-items: center;
}
.caldorra-sim-period-label {
    font-size: 0.95rem;
    color: #4a5568;
}
.caldorra-sim-period-label span:nth-child(2),
.caldorra-sim-period-label span:nth-child(4) {
    font-weight: 700;
    color: #1a2744;
}
.caldorra-sim-phase {
    background: #c9a96e;
    color: #1a2744;
    padding: 6px 14px;
    border-radius: 3px;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}
.caldorra-sim-briefing {
    background: #ffffff;
    border: 1px solid #d8dee8;
    border-left: 4px solid #1a2744;
    padding: 18px 24px;
    margin-bottom: 24px;
    border-radius: 4px;
}
.caldorra-sim-briefing-title {
    font-size: 0.7rem;
    text-transform: uppercase;
    color: #616d88;
    letter-spacing: 0.14em;
    margin-bottom: 8px;
    font-weight: 600;
}
.caldorra-sim-briefing-text {
    font-size: 0.95rem;
    color: #2d3748;
    line-height: 1.55;
}
.caldorra-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 12px;
    margin-bottom: 24px;
}
.caldorra-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #d8dee8;
    border-radius: 4px;
    padding: 18px 18px;
    border-top: 3px solid #1a2744;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.caldorra-sim-kpi-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 16px rgba(15,29,58,0.08);
}
.caldorra-sim-kpi-royalty { border-top-color: #c9a96e; }
.caldorra-sim-kpi-swf { border-top-color: #1a5d8e; }
.caldorra-sim-kpi-tradable { border-top-color: #2d8659; }
.caldorra-sim-kpi-stability { border-top-color: #8e3a59; }
.caldorra-sim-kpi-dividend { border-top-color: #b07d2e; }
.caldorra-sim-kpi-equity { border-top-color: #5b3a8e; }
.caldorra-sim-kpi-label {
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #616d88;
    margin-bottom: 8px;
    font-weight: 600;
}
.caldorra-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
}
.caldorra-sim-kpi-sub {
    font-size: 0.72rem;
    color: #646e81;
    margin-top: 6px;
    letter-spacing: 0.02em;
}
.caldorra-sim-controls {
    background: #ffffff;
    border: 1px solid #d8dee8;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.caldorra-sim-controls h3 {
    font-size: 0.95rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 14px;
    padding-bottom: 8px;
    border-bottom: 1px solid #e0e6ee;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.caldorra-sim-controls h4 {
    font-size: 0.85rem;
    font-weight: 700;
    color: #1a2744;
    margin: 26px 0 12px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.caldorra-sim-control-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 0;
    border-bottom: 1px dashed #e8edf3;
}
.caldorra-sim-control-row label {
    font-size: 0.9rem;
    color: #2d3748;
    margin: 0;
    flex: 1;
}
.caldorra-sim-controls input[type="number"] {
    background: #ffffff;
    border: 1px solid #c5cfdb;
    color: #1a2744;
    padding: 6px 10px;
    border-radius: 3px;
    width: 110px;
    text-align: right;
    font-weight: 600;
    font-size: 0.95rem;
}
.caldorra-sim-controls input[type="number"]:focus {
    outline: none;
    border-color: #1a2744;
    box-shadow: 0 0 0 2px rgba(26,39,68,0.12);
}
.caldorra-sim-controls select {
    background: #ffffff;
    border: 1px solid #c5cfdb;
    color: #1a2744;
    padding: 6px 10px;
    border-radius: 3px;
}
.caldorra-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}
.caldorra-sim-control-sum {
    text-align: right;
    font-size: 0.85rem;
    font-weight: 700;
    margin-top: 14px;
    padding: 10px 14px;
    background: #f4f6f9;
    border-radius: 3px;
    color: #1a2744;
    border: 1px solid #e0e6ee;
}
.caldorra-sim-control-sum.invalid {
    background: #fce8e8;
    color: #8a2727;
    border-color: #f5c5c5;
}
.caldorra-sim-toggle-row {
    display: flex;
    align-items: center;
    padding: 8px 0;
    gap: 12px;
}
.caldorra-sim-toggle-row input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1a2744;
    margin: 0;
    flex-shrink: 0;
}
.caldorra-sim-toggle-row label {
    font-size: 0.88rem;
    color: #2d3748;
    margin: 0;
    flex: 1;
    line-height: 1.4;
}
.caldorra-sim-button-row {
    margin-top: 22px;
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
}
.caldorra-sim-controls #nextPeriodBtn {
    background: #1a2744;
    border-color: #1a2744;
    color: #ffffff;
    padding: 10px 24px;
    font-weight: 600;
    border-radius: 3px;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    font-size: 0.85rem;
}
.caldorra-sim-controls #nextPeriodBtn:hover {
    background: #0f1d3a;
    border-color: #0f1d3a;
}
.caldorra-sim-controls #undoBtn {
    color: #4a5568;
    border-color: #c5cfdb;
    border-radius: 3px;
    background: #ffffff;
}
.caldorra-sim-history {
    background: #ffffff;
    border: 1px solid #d8dee8;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 24px;
    overflow-x: auto;
}
.caldorra-sim-history h3 {
    font-size: 0.95rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 16px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.caldorra-sim-history table {
    width: 100%;
    font-size: 0.83rem;
    margin: 0;
}
.caldorra-sim-history table thead th {
    background: #1a2744;
    color: #ffffff;
    padding: 9px 10px;
    text-transform: uppercase;
    font-size: 0.68rem;
    letter-spacing: 0.08em;
    font-weight: 600;
    border: none;
}
.caldorra-sim-history table td {
    padding: 8px 10px;
    border-bottom: 1px solid #e8edf3;
    color: #2d3748;
}
.caldorra-sim-history table tr:nth-child(even) {
    background: #f9fafc;
}
.caldorra-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(360px, 1fr));
    gap: 16px;
    margin-bottom: 32px;
}
.caldorra-sim-chart-wrap {
    background: #ffffff;
    border: 1px solid #d8dee8;
    border-radius: 4px;
    padding: 16px;
    height: 340px;
    position: relative;
}
@media (max-width: 768px) {
    .caldorra-sim-container { padding: 12px; }
    .caldorra-sim-header { padding: 22px 20px; }
    .caldorra-sim-header h1 { font-size: 1.15rem; }
    .caldorra-sim-period-bar { flex-direction: column; gap: 10px; align-items: flex-start; }
    .caldorra-sim-kpi-grid { grid-template-columns: 1fr 1fr; }
    .caldorra-sim-kpi-value { font-size: 1.3rem; }
    .caldorra-sim-control-row { flex-direction: column; align-items: flex-start; gap: 6px; }
    .caldorra-sim-controls input[type="number"] { width: 100%; }
}

/* --- EQIL a11y additions (2026-08-08) --- */
.caldorra-sim-container :focus-visible {
    outline: 3px solid #0f1d3a;
    outline-offset: 2px;
}
.caldorra-sim-debrief {
    margin-top: 20px;
    padding: 20px 24px;
    background: #ffffff;
    border: 1px solid #d7dce6;
    border-radius: 10px;
    color: #1c2740;
}
.caldorra-sim-debrief h3 { margin: 0 0 8px; font-size: 1.05rem; }
.caldorra-sim-debrief-score { font-size: 1.1rem; margin: 0 0 12px; }
.caldorra-sim-debrief-kpis, .caldorra-sim-debrief-insights { margin: 0 0 12px; padding-left: 20px; }
.caldorra-sim-debrief-lead { font-weight: 600; margin: 0 0 6px; }
@media (prefers-reduced-motion: reduce) {
    .caldorra-sim-container *, .caldorra-sim-container *::before, .caldorra-sim-container *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}

