                bus.on('language:changed', repaint);
                bus.on('period:undone', repaint);
            }
        }

        _paintStatic() {
            var t = function(k) {
                return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k;
            };
            var alts = [['swfChart', 'chart_swf_alt'], ['sectorChart', 'chart_sector_alt']];
            for (var i = 0; i < alts.length; i++) {
                var cv = document.getElementById(alts[i][0]);
                if (cv) { cv.setAttribute('role', 'img'); cv.setAttribute('aria-label', t(alts[i][1])); }
            }
            var C = window.Chart;
            if (C && typeof C.getChart === 'function') {
                var cfg = this.getChartConfig();
                ['swfChart', 'sectorChart'].forEach(function(id) {
                    var ch = C.getChart(id);
                    if (!ch || !cfg[id]) return;
                    cfg[id].data.datasets.forEach(function(dsCfg, k) {
                        if (ch.data.datasets[k]) ch.data.datasets[k].label = dsCfg.label;
                    });
                    try {
                        ch.options.plugins.title.text = cfg[id].options.plugins.title.text;
                        var sc = cfg[id].options.scales || {};
                        Object.keys(sc).forEach(function(ax) {
                            if (sc[ax].title && ch.options.scales[ax] && ch.options.scales[ax].title) ch.options.scales[ax].title.text = sc[ax].title.text;
                        });
                        ch.update('none');
                    } catch (e) { /* silent */ }
                });
            }
        }

        _wireSumIndicator() {
            var self = this;
            var ids = ['pctSWFInput', 'pctSpendingInput', 'pctDividendInput'];
            ids.forEach(function(id) {
                var el = document.getElementById(id);
                if (el && !el._sumWired) {
                    el.addEventListener('input', function() { self._refreshSum(); });
                    el._sumWired = true;
                }
            });
            this._refreshSum();
        }

        _refreshSum() {
            var a = parseFloat((document.getElementById('pctSWFInput') || {}).value) || 0;
            var b = parseFloat((document.getElementById('pctSpendingInput') || {}).value) || 0;
            var c = parseFloat((document.getElementById('pctDividendInput') || {}).value) || 0;
            var s = a + b + c;
            var box = document.getElementById('sumDisplay');
            if (box) {
                var label = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t('sum_label') : 'Total';
                box.innerHTML = label + ': ' + s.toFixed(0) + '%';
                if (Math.abs(s - 100) < 0.5) box.classList.remove('invalid');
                else box.classList.add('invalid');
            }
        }

        _updateBriefing(state) {
            var t = function(k) {
                return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k;
            };
            var period = (state && state.currentPeriod) ? state.currentPeriod : 1;
            var idx = period - 1;
            if (idx < 0) idx = 0;
            var phaseEl = document.getElementById('phaseLabel');
            var briefEl = document.getElementById('briefingText');

            if (idx > 14) {
                if (phaseEl) phaseEl.innerHTML = t('phase_done');
                if (briefEl) briefEl.innerHTML = t('briefing_done_text');
                var dp = document.getElementById('decisionsPanel');
                if (dp) dp.style.display = 'none';
                var ar = document.getElementById('actionRow');
                if (ar) ar.style.display = 'none';
                return;
            }

            var dpOpen = document.getElementById('decisionsPanel');
            if (dpOpen) dpOpen.style.display = '';
            var arOpen = document.getElementById('actionRow');
            if (arOpen) arOpen.style.display = '';

            var phaseKey, briefArr, brIdx;
            if (idx < 5) { phaseKey = 'phase_ramp'; briefArr = this.BRIEFINGS.ramp; brIdx = idx; }
            else if (idx < 10) { phaseKey = 'phase_peak'; briefArr = this.BRIEFINGS.peak; brIdx = idx - 5; }
            else { phaseKey = 'phase_decline'; briefArr = this.BRIEFINGS.decline; brIdx = idx - 10; }

            if (phaseEl) phaseEl.innerHTML = t(phaseKey);
            if (briefEl) briefEl.innerHTML = t(briefArr[brIdx]);
        }

        _syncControlsFromDecisions(decisions) {
            if (!decisions) return;
            var nums = [
                ['pctSWFInput', decisions.pctSWF],
                ['pctSpendingInput', decisions.pctSpending],
                ['pctDividendInput', decisions.pctDividend]
            ];
            for (var i = 0; i < nums.length; i++) {
                var el = document.getElementById(nums[i][0]);
                if (el && nums[i][1] !== undefined && nums[i][1] !== null) el.value = String(nums[i][1]);
            }
            var flags = [
                ['foreignAssetRuleInput', decisions.foreignAssetRule],
                ['structuralRuleInput', decisions.structuralRule],
                ['transparencyInput', decisions.transparency]
            ];
            for (var j = 0; j < flags.length; j++) {
                var fe = document.getElementById(flags[j][0]);
                if (fe && flags[j][1] !== undefined && flags[j][1] !== null) fe.checked = !!flags[j][1];
            }
            if (this._updateAllocSum) { try { this._updateAllocSum(); } catch (e) {} }
        }

        _composite(ds) {
            var totalRoyalties = ds.cumulativeRoyalties || 1;
            var swf = ds.swfBalance || 0;
            var captured = ds.capturedFunds || 0;
            var equityRatio = (swf / totalRoyalties) * 100;
            var score = 0;
            score += Math.min(40, equityRatio * 0.4);
            score += (ds.tradableHealth || 0) * 0.3;
            score += (ds.politicalStability || 0) * 0.3;
            score -= Math.min(30, (captured / totalRoyalties) * 200);
            return { raw: score, composite: Math.max(0, Math.min(100, Math.round(score))), equityRatio: equityRatio };
        }

        _band(score) {
            if (score >= 75) return 'norway';
            if (score >= 55) return 'chile';
            if (score >= 35) return 'midtier';
            if (score >= 15) return 'nigeria';
            return 'venezuela';
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);

            var pctSWF = parseFloat((document.getElementById('pctSWFInput') || {}).value);
            var pctSpending = parseFloat((document.getElementById('pctSpendingInput') || {}).value);
            var pctDividend = parseFloat((document.getElementById('pctDividendInput') || {}).value);

            if (isNaN(pctSWF) || pctSWF < 0 || pctSWF > 100 ||
                isNaN(pctSpending) || pctSpending < 0 || pctSpending > 100 ||
                isNaN(pctDividend) || pctDividend < 0 || pctDividend > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('alloc_warning'), 'warning'
                );
                return false;
            }
            var sum = pctSWF + pctSpending + pctDividend;
            if (Math.abs(sum - 100) > 0.5) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('sum_warning'), 'warning'
                );
                return false;
            }

            decisions.pctSWF = pctSWF;
            decisions.pctSpending = pctSpending;
            decisions.pctDividend = pctDividend;

            var fEl = document.getElementById('foreignAssetRuleInput');
            var sEl = document.getElementById('structuralRuleInput');
            var tEl = document.getElementById('transparencyInput');
            decisions.foreignAssetRule = fEl ? !!fEl.checked : true;
            decisions.structuralRule = sEl ? !!sEl.checked : true;
            decisions.transparency = tEl ? !!tEl.checked : true;

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var idx = Math.min(period - 1, 14);

            // Royalty inflow (USD billions): price × volume × scaling factor
            var price = this.GAS_PRICE_PATH[idx];
            var volume = this.VOLUME_PROFILE[idx];
            var royalty = price * volume * 6.25;

            ds.currentGasPrice = price;
            ds.currentRoyalty = royalty;
            ds.cumulativeRoyalties += royalty;

            // Allocate royalty across the three buckets
            var swfDeposit = royalty * (d.pctSWF / 100);
            var publicSpending = royalty * (d.pctSpending / 100);
            var dividendPool = royalty * (d.pctDividend / 100);

            // SWF returns: 3.0% real if invested abroad (Norway rule), 1.8% if held domestically
            var realReturnRate = d.foreignAssetRule ? 0.03 : 0.018;
            var swfReturn = ds.swfBalance * realReturnRate;
            ds.swfBalance += swfReturn + swfDeposit;
            ds.cumulativeFundReturn += swfReturn;

            // Structural-balance fiscal rule: withdraw 3% of fund into the budget (Hartwick complement)
            var structuralWithdrawal = 0;
            if (d.structuralRule && ds.swfBalance > 1) {
                structuralWithdrawal = ds.swfBalance * 0.03;
                ds.swfBalance -= structuralWithdrawal;
            }

            // Dutch-disease pressure — domestic FX absorption relative to GDP
            var domesticInflow = publicSpending + dividendPool + structuralWithdrawal;
            if (!d.foreignAssetRule) domesticInflow += swfDeposit;
            var gdp = 74 + period * 1.5;
            var ddPressure = (domesticInflow / gdp) * 100;
            var ddDamage = ddPressure * 1.4 - 2.0;
            if (ddDamage < 0) ddDamage = 0;
            ds.tradableHealth -= ddDamage;
            if (ds.tradableHealth < 5) ds.tradableHealth = 5;
            if (ds.tradableHealth > 100) ds.tradableHealth = 100;

            // Per-capita dividend in USD (population 8 million)
            var population = 8e6;
            var perCapitaDividend = (dividendPool * 1e9) / population;
            ds.currentDividend = perCapitaDividend;
            ds.cumulativeDividends += dividendPool;
            ds.cumulativeSpending += publicSpending + structuralWithdrawal;

            // Capture risk: weak transparency leaks the SWF
            var captureRate = 0;
            if (!d.transparency) captureRate += 0.06;
            if (!d.structuralRule) captureRate += 0.02;
            if (!d.transparency && d.pctSWF > 60) captureRate += 0.04;
            var captured = ds.swfBalance * captureRate;
            ds.swfBalance -= captured;
            ds.capturedFunds += captured;

            // Political stability dynamics
            var visibleBenefit = royalty > 0 ? (publicSpending + dividendPool) / royalty : 0;
            var stabilityShift = 0;
            stabilityShift += (visibleBenefit - 0.45) * 8;
            if (idx > 0) {
                var prevPrice = this.GAS_PRICE_PATH[idx - 1];
                var priceDrop = (prevPrice - price) / prevPrice;
                if (priceDrop > 0.2 && !d.structuralRule) stabilityShift -= 12;
            }
            // Dividend visibility bonus, linear in the dividend share: plus 3 at 25 percent as before, no threshold
            stabilityShift += (d.pctDividend / 100) * 12;
            if (captured > 0.5) stabilityShift -= 6;
            if (ds.tradableHealth < 50) stabilityShift -= 4;
            if (d.transparency && d.structuralRule && d.foreignAssetRule) stabilityShift += 1;

            ds.politicalStability += stabilityShift;
            if (ds.politicalStability > 100) ds.politicalStability = 100;
            if (ds.politicalStability < 0) ds.politicalStability = 0;

            // Hartwick reinvestment ratio — fund balance vs total royalties received
            var equityRatio = ds.cumulativeRoyalties > 0
                ? (ds.swfBalance / ds.cumulativeRoyalties) * 100
                : 0;

            // Push to history arrays — required for charts
            ds.swfHistory.push(Math.round(ds.swfBalance * 10) / 10);
            ds.tradableHistory.push(Math.round(ds.tradableHealth));
            ds.stabilityHistory.push(Math.round(ds.politicalStability));
            ds.royaltyHistory.push(Math.round(royalty * 100) / 100);
            ds.equityHistory.push(Math.round(equityRatio));
            ds.dividendHistory.push(Math.round(perCapitaDividend));

            // Grade contract C1: the running composite is persisted every period
            var comp = this._composite(ds);
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: comp.composite });

            // Refresh briefing for the next period
            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
                self._refreshSum();
            }, 500);

            return {
                period: period,
                gasPrice: price,
                royalty: royalty,
                swfDeposit: swfDeposit,
                publicSpending: publicSpending,
                dividendPool: dividendPool,
                perCapitaDividend: perCapitaDividend,
                swfBalance: ds.swfBalance,
                tradableHealth: ds.tradableHealth,
                politicalStability: ds.politicalStability,
                equityRatio: equityRatio,
                captured: captured,
                ddDamage: ddDamage,
                structuralWithdrawal: structuralWithdrawal,
                overallScore: comp.composite,
                score: comp.composite
            };
        }

