        getPerformanceSummary(history) {
            if (!history.length) return {};
            var st = window.mySimulation && window.mySimulation.state;
            var ds = (st && st.domainState) || {};
            var swf = ds.swfBalance || 0;
            var tradable = ds.tradableHealth || 0;
            var stability = ds.politicalStability || 0;
            var captured = ds.capturedFunds || 0;
            var totalRoyalties = ds.cumulativeRoyalties || 1;
            var comp = this._composite(ds);
            var equityRatio = comp.equityRatio;
            var score = comp.raw;

            var t = function(k) {
                return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k;
            };
            var composite = comp.composite;
            var postureKey = this._band(composite);

            var insights = [];
            // Run-specific turning points read from the decision history
            var homeYears = 0, shockNoRule = [];
            for (var hi = 0; hi < history.length; hi++) {
                var hd = (history[hi] && history[hi].decisions) || {};
                var hp = parseInt(history[hi] && history[hi].period, 10) || (hi + 1);
                var px = Math.min(Math.max(hp - 1, 0), 14);
                if (hd.foreignAssetRule === false) homeYears++;
                if (px > 0 && hd.structuralRule === false) {
                    var p0 = this.GAS_PRICE_PATH[px - 1];
                    if ((p0 - this.GAS_PRICE_PATH[px]) / p0 > 0.2) shockNoRule.push(hp);
                }
            }
            if (shockNoRule.length) insights.push(t('insight_rule_shock').split('{years}').join(shockNoRule.join(', ')));
            if (homeYears > 0) insights.push(t('insight_mandate_home').split('{n}').join(String(homeYears)).split('{t}').join(String(history.length)));
            if (equityRatio < 30) insights.push(t('insight_hartwick'));
            if (tradable < 60) insights.push(t('insight_dutch'));
            if (stability < 50) insights.push(t('insight_fragility'));
            if (captured > 2) insights.push(t('insight_capture'));
            if (equityRatio > 55 && tradable > 75 && stability > 70 && captured < 1) {
                insights.push(t('insight_norway'));
            }
            if (insights.length === 0) {
                insights.push(t('insight_mixed'));
            }

            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                rawScore: Math.round(score),
                rounds: history.length,
                totalRoyalties: totalRoyalties,
                swfFinal: swf,
                equityRatio: equityRatio,
                tradableHealth: tradable,
                politicalStability: stability,
                capturedFunds: captured,
                performance: postureKey,
                performanceKey: postureKey,
                performanceLabel: t('posture_' + postureKey),
                insights: insights
            };
        }

