        getHint(state, results) {
            if (!results) return null;
            if (results.ddDamage > 4) return window.mySimulation.t('hint_dutch_disease');
            if (results.captured > 0.3) return window.mySimulation.t('hint_capture');
            if (state.domainState.politicalStability < 40) return window.mySimulation.t('hint_stability');
            if (state.domainState.tradableHealth < 50) return window.mySimulation.t('hint_tradable');
            var totalR = state.domainState.cumulativeRoyalties;
            if (state.currentPeriod >= 5 && totalR > 0 && (state.domainState.swfBalance / totalR) < 0.2) {
                return window.mySimulation.t('hint_hartwick');
            }
            return null;
        }

